In batch annotation pipelines, the LLM processes each text independently without access to $Y$, making non-differentiality an architectural invariant~\cite{ziems2024can}; Y-stratified permutation tests confirm this (1/12 rejection at $\alpha{=}0.05$; Appendix~\ref{sec:y_stratified_test}). Non-differentiality may be violated when $Y$ correlates with text content, in which case our Y-stratified test provides empirical verification. Under stress testing, sign reversal occurs in 14/16 $K{\geq}3$ exposure configurations at $\varepsilon{=}0.01$ departure (Appendix~\ref{sec:nondiff_stress}).

Throughout, $\tau$ denotes the causal estimand of interest, whose definition varies by topology: the confounder's coefficient, the treatment effect, the indirect effect, or the Wald ratio (Appendix~\ref{app:confounding}ff.).

We study seven canonical DAG topologies (Figure~\ref{fig:dag_taxonomy})~\cite{pearl2009, hernan2020causal}, deriving probability limits under linear SEMs~\cite{carroll2006}; logistic regression robustness is verified in Appendix~\ref{sec:logistic_dgp} and~\ref{sec:fwl_nonlinear}.

\subsection{Multi-Class Bias Expressions}
\label{sec:bias_expressions}

For each topology, we derive the $\text{plim}$\footnote{The probability limit (plim) is the value to which an estimator converges as sample size $N \to \infty$; it characterizes systematic bias separately from sampling variability.} of the naive estimator that substitutes $A^*$ for $A$. Let $\tau$ denote the target causal parameter---its precise definition is topology-specific (e.g., the coefficient on $X$ for confounding, the category-specific $\beta_j$ for exposure, or the direct effect $\tau_{\text{direct}}$ for mediation)---and $\hat{\tau}(A^*)$ the estimator using misclassified annotations.

\paragraph{Confounding ($A$ = confounder).}
When $A$ confounds the $X{\to}Y$ relationship, the OLS estimator controlling for $A^*$ has probability limit
\begin{equation}
\label{eq:confounding}
\text{plim}\;\hat{\tau}(A^*) = \bigl(\mathbb{E}[Z^{\prime}Z]\bigr)^{-1}\mathbb{E}[Z^{\prime}X]\,\boldsymbol{\beta},
\end{equation}
where $Z = [X, \text{dummies}(A^*)]$, $\boldsymbol{\beta}$ contains the true coefficients, and the target parameter $\tau$ is the coefficient on $X$. Misclassification produces residual confounding that monotonically approaches the omitted variable bias, but the sign of $\hat{\tau}$ is preserved: $\tau_{\text{sign\_flip}} = 0$ structurally.\footnote{Consistent with \citet{brenner1993}: misclassification degrades confounding control, producing amplification ($|\hat{\tau}| > |\tau|$, universal in this topology) but never sign reversal ($\text{sign}(\hat{\tau}) \neq \text{sign}(\tau)$).}

\paragraph{Exposure ($A$ = treatment variable).}
When $A$ is the exposure of interest, the biased coefficient for category $j$ becomes a weighted combination of true coefficients:
\begin{equation}
\label{eq:exposure}
\text{plim}\;\hat{\beta}_j(A^*) = \sum_{k=1}^{K} w_{jk}\,\beta_k,
\end{equation}
where $w_{jk}$ depends on the confusion matrix $C$ and the population marginal $\pi_k = P(A{=}k)$. Unlike binary misclassification~\cite{brenner1993}, $K{\geq}3$ permits $w_{jk}$ to assign negative weight to categories with opposite-sign coefficients, producing \emph{sign reversal} (83.4\% under uniform Dirichlet prior)---structurally impossible at $K{=}2$.

\begin{figure*}[t]
\centering
\includegraphics[width=\textwidth]{fig2_bias_distribution.pdf}
\caption{Bias distributions under 100{,}000 random $K{=}3$ confusion matrices (uniform Dirichlet; realistic-accuracy results in Section~\ref{sec:taxonomy_results}). Red = sign reversal. Exposure: 83.4\% sign reversal; IV: 52.6\%.}
\label{fig:bias_distribution}
\end{figure*}

\paragraph{Numerical Verification 2: Primary coefficient preservation.}
Across 23 empirical LLM configurations, the primary coefficient (the category with the largest true effect $|\beta_k|$) never reverses sign, while 61\% reverse a secondary (non-dominant) coefficient---confirmed under 100{,}000 Dirichlet matrices with diagonal ${\geq}\,0.7$ across six beta-ratio conditions (1.0 to 50.0) with 0\% primary sign-flip (Appendix~\ref{app:exposure}).

\paragraph{Mediation ($A$ = mediator).}
When $A$ mediates the $X{\to}Y$ relationship~\cite{vanderweele2015explanation}, the direct effect estimator controlling for $A^*$ has probability limit
\begin{equation}
\label{eq:mediation}
\text{plim}\;\hat{\tau}_{\text{direct}}(A^*) = \tau_{\text{direct}} + \bigl(1 - \lambda(C)\bigr)\,\tau_{\text{indirect}},
\end{equation}
where $\lambda(C) \in [0,1]$ under proportional effects (Appendix~\ref{app:proof}, Proposition~\ref{prop:lambda_bound}), with $\lambda(I) = 1$ under perfect classification. Misclassification ($\lambda < 1$) causes the residual indirect effect to be absorbed into the direct path estimate, producing upward bias in $|\hat{\tau}_{\text{direct}}|$ but preserving the sign ($\tau_{\text{sign\_flip}} = 0$).

\paragraph{Collider, M-bias, and front-door.}
Three topologies exhibit protective or immune behavior. \textbf{Collider:} conditioning on $A^*$ instead of $A$ attenuates the spurious path, so annotation error reduces collider bias ($\tau_{\text{sign\_flip}} = 0$). \textbf{M-bias:} in the M-shaped DAG~\cite{greenland2003}, misclassifying $A$ weakens the M-bias path; this topology is immune ($\text{ASV} = \infty$). \textbf{Front-door:} the front-door estimator~\cite{bellemare_bloem2024} is attenuated in both $X \to A$ and $A \to Y$ stages, producing moderate bias with $\tau_{\text{sign\_flip}} = 0$.

\paragraph{Instrumental variable ($A$ = instrument).}
The Wald estimator~\cite{angrist_imbens1995} $\hat{\tau}_{\text{IV}} = \hat{\text{cov}}(A^*, Y) / \hat{\text{cov}}(A^*, X)$ has $C$ in the denominator. Misclassification can drive first-stage coefficients toward zero or reverse their sign; under random Dirichlet matrices, 52.6\% produce sign reversal, making IV the most fragile topology (Appendix~\ref{sec:iv_dirichlet_subspace}).

\paragraph{Structural sign-flip guarantee.}
\begin{proposition}[Sign preservation---analytic results]
\label{prop:signflip}
Under non-differential misclassification with $C_{kk} > 0$ for all $k$:
\emph{(a)}~Confounding preserves sign when $\operatorname{sign}(\tau) = \operatorname{sign}(\tau {+} B_{\mathrm{OV}})$, where $B_{\mathrm{OV}} {=} \operatorname{Cov}(g(A),f(A))/\operatorname{Var}(T)$ is the omitted-variable bias (Cauchy--Schwarz; Appendix~\ref{app:confounding}).
\emph{(b)}~Collider preserves sign when $|\tau| > \sqrt{\operatorname{Var}(g)\operatorname{Var}(h)}/\mathbb{E}[\operatorname{Var}(T{\mid}A)]$ (Berkson attenuation; Appendix~\ref{app:collider}); empirically verified across 100{,}000 matrices with zero violations.
\emph{(c)}~Exposure can produce sign reversal for $K {\geq} 3$, even with $C_{kk} {>} 0.5$ (counterexample in Appendix~\ref{app:exposure}).
\end{proposition}

Sign preservation for non-exposure topologies holds under topology-specific conditions (Table~\ref{tab:sign_conditions}, Appendix~\ref{app:conditions}), verified across 100{,}000 random matrices with zero violations; analytic proofs for general $K$ remain open.

\subsection{Annotation Sensitivity Values}
\label{sec:asv}

We adapt the sensitivity analysis paradigm---E-values~\cite{vanderweele_ding2017}, partial-$R^2$ bounds~\cite{cinelli2020making}, coefficient stability~\cite{oster2019}---to $K{\times}K$ annotation error, defining Annotation Sensitivity Values (ASVs): we prove $\varepsilon$-approximate monotonicity along $C(\delta)$ (Theorem~\ref{thm:monotone}), reducing $K^2$ dimensions to a scalar; define three ASV diagnostics for topology-dependent failure modes; and combine ASVs with FWL invariance to route corrections.

\paragraph{Parameterization.}
We set $C(\delta) = (1{-}\delta)I + \delta C_0$, where $C_0$ is a reference confusion matrix and $\delta \in [0,1]$ controls severity ($\delta{=}0$: perfect; $\delta{=}1$: matches $C_0$). This linear path is one of many in the column-stochastic polytope from $I$ to $C_0$; ASV thresholds are path-dependent, but our bootstrap procedure (Section~\ref{sec:asv_results}) captures estimation uncertainty along the empirical path. We recommend bootstrapping $C_0$ and reporting ASV confidence intervals (Appendix~\ref{sec:bootstrap_asv}).
\paragraph{Three ASV types.}
We define three complementary measures: (1)~\textbf{Magnitude ASV} $\delta^*_{\text{mag}} = \min\{\delta : |\text{plim}\;\hat{\tau}(C(\delta)) - \tau| > \epsilon\}$---analogous to E-values; (2)~\textbf{Significance ASV} $\delta^*_{\text{sig}} = \min\{\delta : |\text{plim}\;\hat{\tau}(C(\delta))| < z_{\alpha/2} \cdot SE(N)\}$---relevant for attenuating topologies; (3)~\textbf{Sign-flip ASV} $\delta^*_{\text{sf}} = \min\{\delta : \text{sign}(\hat{\tau}) \neq \text{sign}(\tau)\}$---exposure and IV only. The significance ASV depends on $N$ through $SE(N)$, exhibiting a sharp phase transition at a critical $N^*$ below which all rejections are blocked.

\begin{theorem}[Envelope monotonicity---$K{=}2$]
\label{thm:monotone}
For $K{=}2$ confounding and mediation topologies with proportional effects ($f = \lambda g$ for some scalar $\lambda$) under $C(\delta) = (1{-}\delta)I + \delta C_0$ with $(C_0)_{jj} \geq \tfrac{1}{2}$, $|B(C(\delta))|$ is monotonically non-decreasing in $\delta \in [0,1]$.
\end{theorem}

The proof (Appendix~\ref{app:monotonicity_proof},~\ref{par:med_monotone}) exploits perspective function convexity. Proportional effects ($f{=}\lambda g$) is plausible when overall annotation competence drives both paths; all 23 empirical configurations preserve sign, with 97.3\% under non-proportional effects (Appendix~\ref{sec:proportional_effects}).

\begin{theorem}[$K{=}3$ symmetric monotonicity]
\label{thm:k3_symmetric}
For $K{=}3$ with symmetric confusion matrix $C_{jk} = c$ for $j \neq k$ and $C_{kk} = 1{-}2c$, $c \in (0, 1/3)$, and proportional effects ($f{=}\lambda g$), envelope monotonicity holds exactly: $|B(C(\delta))|$ is strictly monotone in $\delta$ for confounding, mediation, and collider topologies whenever $\mathrm{Var}(g) > 0$.
\end{theorem}

Theorem~\ref{thm:k3_symmetric} anchors exact monotonicity at $K{=}3$; for general asymmetric matrices ($d_{\mathrm{rel}}{=}0.33$; Remark~\ref{rem:symmetry}), Conjecture~\ref{conj:monotone} provides $\varepsilon < 0.017$ coverage. The proof exploits the reduction $s = c\delta$ (Appendix~\ref{app:k3_symmetric_proof}).

\paragraph{From proofs to numerical evidence.}
Exact monotonicity (Theorems~\ref{thm:monotone}--\ref{thm:k3_symmetric}) does not extend to general $K{\geq}3$ column-stochastic structures; we state a conjecture supported by numerical evidence:

\begin{conjecture}[$\varepsilon$-approximate envelope monotonicity]
\label{conj:monotone}
For general $K{\geq}3$ non-IV topologies under $C(\delta) = (1{-}\delta)I + \delta C_0$, $|B(C(\delta))|$ is $\varepsilon$-approximately monotonic with $\varepsilon < 0.02$ for $|\beta| \leq 1$, scaling with effect magnitude (Table~\ref{tab:conjecture_verify},~\ref{tab:dgp_sensitivity}; Appendix~\ref{sec:conjecture_verify}). The safe/fragile partition---five sign-preserving topologies versus exposure and IV---is robust across all tested parameterizations.
\end{conjecture}

Numerical support spans 100{,}000 Dirichlet matrices and 545{,}945 adversarial curves (Appendix~\ref{app:adversarial_monotonicity}).

\begin{remark}[ASV and E-values as complementary tools]
\label{rem:evalue}
ASV and E-values~\cite{vanderweele_ding2017} address orthogonal sources---annotation error vs.\ unmeasured confounding---and are most valuable jointly (Table~\ref{tab:sensitivity_comparison}, Appendix). ASV is topology-dependent and targets sign-flip failure modes absent from confounding analysis.
\end{remark}

Under alternating-sign effects ($\boldsymbol{\beta}{=}[0,\,1.0,\,-0.5]$), magnitude ASV ranges from 0.09 (exposure) to $\infty$ (M-bias), a $4{\times}$ difference determined by topology (Table~\ref{tab:asv_stability}). Sign-flip ASV $< 1$ flags sign-reversal-prone pairs; magnitude ASV $< \delta_{\text{observed}}$ indicates bias exceeds tolerance (Algorithm~\ref{alg:correction}); the safe/fragile partition is stable across parameterizations ($\varepsilon < 0.02$; Appendix~\ref{sec:asv_stability}).

% K=3 Symmetric Confusion Matrix: Monotonicity Proof
% Theorem statement is in method.tex; this file contains the proof and remarks only.

\begin{proof}
All three parts reduce to a single lemma about the between-group variance
$V_B(\delta)=\operatorname{Var}\bigl(\mathbb{E}[g(A)\mid A^*_\delta]\bigr)$.

\paragraph{Step 1: Structural reduction.}
The symmetric $C_0$ decomposes as $C_0=(1{-}3c)\,I+c\,\mathbf{1}\mathbf{1}^\top$, so
\begin{multline*}
  C(\delta) = (1{-}\delta)I + \delta\bigl[(1{-}3c)\,I+c\,\mathbf{1}\mathbf{1}^\top\bigr]\\
  = (1{-}3c\delta)\,I + c\delta\,\mathbf{1}\mathbf{1}^\top.
\end{multline*}
Setting $s=c\delta\in[0,c]$, each entry is
$C(\delta)_{j\ell}=(1{-}3s)\,\mathbf{1}_{j=\ell}+s$,
so $C(\delta)$ stays in the one-parameter symmetric family.
In particular:
\begin{align}
  q_j(s) &= \textstyle\sum_k C(\delta)_{jk}\,p_k = (1{-}3s)\,p_j + s, \label{eq:k3q} \\
  \mu_j(s) &\equiv \mathbb{E}[g(A)\mid A^*{=}j]
  = \bar{g} + \frac{(1{-}3s)\,p_j\,h_j}{q_j(s)}, \label{eq:k3mu}
\end{align}
where $h_j=g_j-\bar{g}$, $\bar{g}=\sum_k p_k g_k$.

\paragraph{Step 2: Closed-form $V_B(s)$.}
The between-group variance admits a clean factorization:
\begin{equation}
  V_B(s) = \sum_j q_j\,(\mu_j-\bar{g})^2
  = (1{-}3s)^2\sum_{j=0}^{2}\frac{p_j^2\,h_j^2}{q_j(s)}.
  \label{eq:k3VB}
\end{equation}
\emph{Verification.}
At $s{=}0$: $q_j{=}p_j$, so $V_B(0)=\sum_j p_j h_j^2=\operatorname{Var}(g)$.
At $s{=}\tfrac{1}{3}$: $V_B(\tfrac{1}{3})=0$.

\paragraph{Step 3: $V_B$ is strictly decreasing on $[0,\tfrac{1}{3})$ (pointwise, not just at endpoints).}
Differentiating~\eqref{eq:k3VB} via the product rule:
\begin{equation}
  \frac{dV_B}{ds}
  = (1{-}3s)\!\sum_{j=0}^{2}\frac{p_j^2 h_j^2}{q_j^2}\bigl[\underbrace{-3(1{-}3s)p_j - 1 - 3s}_{\Lambda_j(s)}\bigr].
  \label{eq:k3dVB}
\end{equation}

\emph{Derivation.}
Write $V_B=(1{-}3s)^2 F(s)$ with $F(s)=\sum_j p_j^2 h_j^2/q_j(s)$.
The product rule gives $V_B'=-6(1{-}3s)F+(1{-}3s)^2 F'$.
Since $q_j'(s)=1{-}3p_j$, we have $F'(s)=\sum_j p_j^2 h_j^2(3p_j{-}1)/q_j^2$.
Combining:
\begin{align*}
  V_B'
  &= (1{-}3s)\Bigl[-6\textstyle\sum_j \frac{p_j^2 h_j^2}{q_j}\\
  &\quad{}+(1{-}3s)\textstyle\sum_j \frac{p_j^2 h_j^2(3p_j{-}1)}{q_j^2}\Bigr] \\
  &= (1{-}3s)\textstyle\sum_j \frac{p_j^2 h_j^2}{q_j^2}\bigl[-6q_j+(1{-}3s)(3p_j{-}1)\bigr].
\end{align*}
Expanding the bracket:
\begin{align*}
  &-6q_j+(1{-}3s)(3p_j{-}1)\\
  &\quad= -6(1{-}3s)p_j-6s+3(1{-}3s)p_j-(1{-}3s)\\
  &\quad= -3(1{-}3s)p_j-1-3s
  = \Lambda_j(s).
\end{align*}

\emph{Sign analysis.}
For $s\in[0,\tfrac{1}{3})$: $(1{-}3s)>0$, $p_j\geq 0$, so
\[
  \Lambda_j(s) = -3(1{-}3s)\,p_j - (1+3s) < 0
  \quad\text{for all } j,
\]
since $1+3s>0$ alone forces $\Lambda_j<0$.
Every term $p_j^2 h_j^2/q_j^2\geq 0$, and the prefactor $(1{-}3s)>0$.
Hence $dV_B/ds\leq 0$ for all $s\in[0,\tfrac{1}{3})$.

\emph{Strict inequality.}
If $\operatorname{Var}(g){>}0$, at least two categories $j$ satisfy $p_j>0$ and $h_j\neq 0$, contributing strictly positive terms.
Since $\Lambda_j<0$, the sum is strictly negative:
$dV_B/ds<0$ for all $s\in(0,\tfrac{1}{3})$.

\paragraph{Step 4: From $V_B$ to $|B|$ --- confounding (a).}
Under proportional effects $f=\lambda g$ (Proposition~\ref{prop:conf_prop}):
\begin{gather*}
  B(C(\delta)) = \frac{\lambda\,V_W(\delta)}{V_W(\delta)+\sigma_T^2},\\
  V_W(\delta)=\operatorname{Var}(g)-V_B(c\delta).
\end{gather*}
Step~3 shows $V_B(s)$ is strictly decreasing in $s=c\delta$, so $V_W(\delta)$ is strictly increasing from $0$ to $\operatorname{Var}(g)$.
Since $x\mapsto |\lambda|\,x/(x+\sigma_T^2)$ is strictly increasing for $x\geq 0$:
\[
  |B(C(\delta))| = |\lambda|\,\frac{V_W(\delta)}{V_W(\delta)+\sigma_T^2}
\]
is strictly non-decreasing.

\paragraph{Step 5: Mediation (b).}
Under proportional effects $f=\lambda g$ with $g(k)=\mathbb{E}[T\mid A{=}k]$, the mediation bias
(§\ref{par:med_monotone}) has the identical form
$B=\lambda\,V_W/(V_W+\sigma_\varepsilon^2)$
with $\sigma_\varepsilon^2=\mathbb{E}[\operatorname{Var}(T\mid A)]$ replacing $\sigma_T^2$.
The same argument yields $|B|$ strictly non-decreasing.

\paragraph{Step 6: Collider (c).}
Under proportional effects $h=\lambda g$ (Proposition~\ref{prop:col_prop}):
\begin{gather*}
  B_{\mathrm{col}}(C(\delta)) = -\frac{\lambda\,V_B(c\delta)}{\operatorname{Var}(T)-V_B(c\delta)},\\
  |B_{\mathrm{col}}| = |\lambda|\,\frac{V_B(c\delta)}{\operatorname{Var}(T)-V_B(c\delta)}.
\end{gather*}
Since $x\mapsto x/(a{-}x)$ is strictly increasing for $x\in[0,a)$
and $V_B(s)$ is strictly decreasing (Step~3),
$|B_{\mathrm{col}}(C(\delta))|$ is strictly non-increasing:
from $|B_{\mathrm{Berkson}}|=|\lambda|\,V_g/(\operatorname{Var}(T){-}V_g)$ at $\delta{=}0$
to $0$ at $\delta$ such that $V_B\to 0$.
\end{proof}

\begin{remark}[Comparison with the general-$K$ proof]
\label{rem:k3_vs_general}
The general-$K$ monotonicity proof (§\ref{app:monotonicity_proof}) relies on
convexity of $V_B(\delta)$ plus the endpoint condition $V_B'(1)\leq 0$,
the latter verified only for $K{=}2$ analytically and $K\geq 3$ numerically.
The $K{=}3$ symmetric proof is stronger:
it establishes $dV_B/ds<0$ at every interior point via the signed decomposition~\eqref{eq:k3dVB},
bypassing both the convexity argument and the endpoint condition entirely.
The key enabler is that the symmetric $C_0$ keeps $C(\delta)$ within the one-parameter family
$(1{-}3s)I+s\,\mathbf{1}\mathbf{1}^\top$, yielding the factored form~\eqref{eq:k3VB}
in which the $(1{-}3s)^2$ prefactor and the $q_j^{-1}$ terms interact to produce
a uniformly signed derivative.
\end{remark}

\begin{remark}[General (non-proportional) effects]
\label{rem:k3_general}
For non-proportional effects ($f\neq\lambda g$), the confounding bias
$B(C)=\mathbb{E}[\operatorname{Cov}(g,f\mid A^*)]/D(C)$
does not factor through $V_W$ alone,
and exact monotonicity of $|B(C(\delta))|$ can fail even for $K{=}3$ symmetric $C_0$.
Numerical verification ($50{,}000$ random configurations) finds violations in ${\sim}10\%$ of cases,
with maximum step deviation ${\sim}0.004$,
confirming $\varepsilon$-approximate monotonicity consistent with the general-$K$ results
(Table~\ref{tab:conjecture_verify}).
\end{remark}

